import { defineCollection } from 'astro:content';
import { z } from 'astro/zod';

export function universalLoader({ endpoint, collectionName }: { endpoint: string; collectionName: string }) {
  return {
    name: `universal-${collectionName}`,
    load: async ({ store, logger, parseData }: any) => {
      const res = await fetch(endpoint);
      if (!res.ok) throw new Error(`Fetch failed: ${res.statusText}`);
      const items = await res.json();
      store.clear();
      for (const item of (Array.isArray(items) ? items : items.data)) {
        const id = String(item.id || item.slug || crypto.randomUUID());
        const parsed = await parseData({ id, data: item });
        store.set({ id, data: parsed });
      }
    }
  };
}

astro_action_nats_valkey.code:
import { defineAction, ActionError } from 'astro:actions';
import { z } from 'astro/zod';
import { connect, JSONCodec } from 'nats';
import Redis from 'ioredis';

const jc = JSONCodec();
const valkey = new Redis(process.env.VALKEY_URL || 'redis://valkey:6379');

export const server = {
  submitInquiry: defineAction({
    accept: 'json',
    input: z.object({
      email: z.string().email(),
      name: z.string().min(2),
      message: z.string().min(10)
    }),
    handler: async (input, context) => {
      const ip = context.clientAddress || '127.0.0.1';
      const hits = await valkey.incr(`rate:inquiry:${ip}`);
      if (hits === 1) await valkey.expire(`rate:inquiry:${ip}`, 60);
      if (hits > 10) throw new ActionError({ code: 'TOO_MANY_REQUESTS', message: 'Rate limit exceeded.' });
      const nc = await connect({ servers: process.env.NATS_URL || 'nats://nats:4222' });
      nc.publish('events.inquiry.created', jc.encode({ id: crypto.randomUUID(), data: input }));
      await nc.drain();
      return { success: true };
    }
  })
};

